<template>
  <q-page padding class="validation-demo-page">
    <h1 class="demo-title" data-test="validation-report-demo-title">Validation Report — L0 to L4 Demo</h1>
    <p class="demo-intro">
      Hidden dev page that mounts
      <code>ValidationReportPanel</code>
      with synthetic <code>ValidationReport</code>s, one per layer. Use this
      to verify that the error page renders the right explanation for
      each L0–L4 finding without needing a live backend pipeline.
    </p>

    <div class="layer-buttons q-gutter-md">
      <q-btn
        v-for="key in Object.keys(scenarios)"
        :key="key"
        :data-test="`open-${key}`"
        color="primary"
        unelevated
        @click="openScenario(key as ScenarioKey)"
      >
        {{ scenarios[key as ScenarioKey].label }}
      </q-btn>
    </div>

    <ValidationReportPanel v-model="dialogOpen" :report="activeReport" />
  </q-page>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

import ValidationReportPanel from 'src/pages/Components/ValidationReportPanel.vue';
import type {
  ValidationFinding,
  ValidationReport,
} from 'src/types/validationReport';

interface Scenario {
  label: string;
  build: () => ValidationReport;
}

type ScenarioKey =
  | 'L0_pdfa_not_a3'
  | 'L0b_attachment_missing'
  | 'L1_malformed_xml'
  | 'L2_xsd_violation'
  | 'L3_schematron_br_de_1'
  | 'L4_iban_checksum'
  | 'all_green';

function emptySummary() {
  return {
    L0: { status: 'ok', errors: 0, warnings: 0, info: 0 },
    L0b: { status: 'ok', errors: 0, warnings: 0, info: 0 },
    L1: { status: 'ok', errors: 0, warnings: 0, info: 0 },
    L2: { status: 'ok', errors: 0, warnings: 0, info: 0 },
    L3: { status: 'ok', errors: 0, warnings: 0, info: 0 },
    L4: { status: 'ok', errors: 0, warnings: 0, info: 0 },
  };
}

function reportWith(
  findings: ValidationFinding[],
  base: Partial<ValidationReport> = {},
): ValidationReport {
  const summary = emptySummary();
  for (const f of findings) {
    const layer = summary[f.layer as keyof typeof summary];
    if (!layer) continue;
    if (f.severity === 'fatal' || f.severity === 'error') {
      layer.errors += 1;
    } else if (f.severity === 'warning') {
      layer.warnings += 1;
    } else {
      layer.info += 1;
    }
    const parts: string[] = [];
    if (layer.errors)
      parts.push(`${layer.errors} error${layer.errors !== 1 ? 's' : ''}`);
    if (layer.warnings)
      parts.push(
        `${layer.warnings} warning${layer.warnings !== 1 ? 's' : ''}`,
      );
    if (layer.info) parts.push(`${layer.info} info`);
    layer.status = parts.length ? parts.join(', ') : 'ok';
  }
  const isValid = findings.every(
    (f) => f.severity !== 'fatal' && f.severity !== 'error',
  );
  return {
    xrechnung_type: 'urn:demo:einvoice:v1',
    syntax: 'UBL',
    profile: 'DEMO',
    version: 'v1',
    is_valid: isValid,
    summary,
    findings,
    bundle_version: 'demo-v1',
    ...base,
  };
}

const scenarios: Record<ScenarioKey, Scenario> = {
  L0_pdfa_not_a3: {
    label: 'L0 — PDF/A-3 missing',
    build: () =>
      reportWith([
        {
          layer: 'L0',
          severity: 'fatal',
          code: 'PDFA-NOT-A3',
          field: null,
          xpath: null,
          line: null,
          column: null,
          value: null,
          message:
            "PDF declares pdfaid:part='1', expected '3'. ZUGFeRD/Factur-X requires PDF/A-3.",
        },
      ]),
  },
  L0b_attachment_missing: {
    label: 'L0b — XML attachment missing',
    build: () =>
      reportWith([
        {
          layer: 'L0b',
          severity: 'fatal',
          code: 'FX-AF-MISSING',
          field: null,
          xpath: null,
          line: null,
          column: null,
          value: null,
          message:
            "No embedded XML attachment matching ['ZUGFeRD-invoice.xml', 'factur-x.xml', 'xrechnung.xml'] found. ZUGFeRD/Factur-X requires the invoice XML embedded as an attached file.",
        },
      ]),
  },
  L1_malformed_xml: {
    label: 'L1 — Malformed XML',
    build: () =>
      reportWith([
        {
          layer: 'L1',
          severity: 'fatal',
          code: 'XML-PARSE',
          field: null,
          xpath: null,
          line: 5,
          column: 12,
          value: null,
          message:
            'Premature end of data in tag Invoice line 1, line 5, column 12',
        },
      ]),
  },
  L2_xsd_violation: {
    label: 'L2 — XSD violation',
    build: () =>
      reportWith([
        {
          layer: 'L2',
          severity: 'error',
          code: 'XSD-CVC-COMPLEX-TYPE-2-4-A',
          field: null,
          xpath: '/ubl:Invoice',
          line: 4,
          column: 1,
          value: null,
          message:
            "Element '{urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2}IssueDate': This element is not expected. Expected is ( {urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2}ID ).",
        },
      ]),
  },
  L3_schematron_br_de_1: {
    label: 'L3 — Schematron BR-DE-1',
    build: () =>
      reportWith([
        {
          layer: 'L3',
          severity: 'error',
          code: 'BR-DE-1-DEMO',
          field: 'BT-10',
          xpath: '/ubl:Invoice',
          line: null,
          column: null,
          value: null,
          message:
            'BuyerReference (BT-10) must be present (Leitweg-ID for B2G).',
        },
      ]),
  },
  L4_iban_checksum: {
    label: 'L4 — IBAN checksum',
    build: () =>
      reportWith([
        {
          layer: 'L4',
          severity: 'error',
          code: 'VAL-IBAN-CHECKSUM',
          field: 'BT-84',
          xpath:
            '/ubl:Invoice/cac:PaymentMeans/cac:PayeeFinancialAccount/cbc:ID',
          line: null,
          column: null,
          value: 'DE99999999999999999999',
          message:
            "IBAN 'DE99999999999999999999' is invalid: Invalid IBAN checksum digits. Expected mod-97 checksum and country-specific length.",
        },
      ]),
  },
  all_green: {
    label: 'All layers pass',
    build: () => ({
      ...reportWith([]),
      is_valid: true,
    }),
  },
};

export default defineComponent({
  name: 'ValidationReportDemo',
  components: { ValidationReportPanel },
  data() {
    return {
      dialogOpen: false,
      activeReport: null as ValidationReport | null,
      scenarios,
    };
  },
  methods: {
    openScenario(key: ScenarioKey) {
      this.activeReport = scenarios[key].build();
      this.dialogOpen = true;
    },
  },
});
</script>

